  .feed { position: absolute; right: 12px; bottom: 12px; width: min(300px, calc(100% - 24px)); background: rgba(16, 22, 44, .9); border: 1px solid rgba(255, 255, 255, .1); border-radius: var(--radius-m); padding: 10px 12px 11px; color: #E3E7F5; -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); cursor: default; }
