  dialog.ask label { display: block; font-size: 13px; color: var(--muted); margin: 4px 0 4px; }
  dialog.ask input { width: 100%; border: 1px solid var(--rule); border-radius: var(--radius-s); padding: 9px 12px; background: #fff; }
  dialog.ask .err { min-height: 1.2em; margin: 8px 0 0; font-size: 13.5px; color: var(--fail); }
  dialog.ask .letter-actions { margin-top: 14px; }

  .editor label { display: block; font-size: 13px; color: var(--muted); margin: 0 0 4px; }
  .editor input, .editor textarea { width: 100%; max-width: 640px; border: 1px solid var(--rule); border-radius: var(--radius-s); padding: 10px 12px; background: #fff; }
  .editor textarea { font-family: var(--letter); font-size: 17px; line-height: 1.55; min-height: 230px; resize: vertical; margin-top: 2px; }
  .editor .live-checks { margin-top: 10px; }

  .quote { margin: 0; font-family: var(--letter); font-size: 17px; line-height: 1.5; border-left: 3px solid var(--line); padding: 2px 0 2px 14px; }
  .src { margin-top: 8px; font-size: 13px; color: var(--muted); }
  .verified { display: inline-flex; align-items: center; gap: 6px; color: var(--pass); font-weight: 600; font-size: 13px; margin-top: 8px; }
  .rejected { color: var(--warn); font-size: 14px; }

  .passes { display: flex; gap: 0; flex-wrap: wrap; }
  .pass { flex: 1 1 160px; padding: 10px 14px; border: 1px solid var(--rule); margin: 0 -1px -1px 0; }
  .pass:first-child { border-radius: var(--radius-s) 0 0 var(--radius-s); }
  .pass:last-child { border-radius: 0 var(--radius-s) var(--radius-s) 0; }
  .pass .n { font-size: 13px; color: var(--muted); }
  .pass .sc { font-size: 26px; font-weight: 600; font-variant-numeric: tabular-nums; }
  .pass .sc small { font-size: 13px; color: var(--muted); font-weight: 500; }
  .pass.ok .sc { color: var(--pass); }
  .pass ul { margin: 6px 0 0; padding-left: 16px; font-size: 13px; color: var(--muted); }

  .checks { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 6px 18px; }
  .checks li { display: flex; gap: 8px; align-items: flex-start; font-size: 14px; }
  .checks li svg { flex: none; margin-top: 3px; }
  .checks li.no { color: var(--fail); }
  .checks li .d { display: block; font-size: 12.5px; color: var(--muted); }

  .notes { margin: 0; padding-left: 18px; }
  .notes li { margin: 3px 0; }
  .notes b { font-weight: 600; color: var(--ink); }
  .two { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
  @media (max-width: 1100px) { .two { grid-template-columns: 1fr; } }

  .empty { text-align: center; padding: 56px 24px; }
  .empty h2 { margin: 0 0 6px; font-size: 22px; }
  .empty p { color: var(--muted); margin: 0 auto 16px; max-width: 46ch; }

  .foot { padding: 0 28px 24px; color: var(--muted); font-size: 12.5px; }
  .toast { position: fixed; left: 50%; bottom: 22px; transform: translate(-50%, 20px); opacity: 0; background: var(--ink); color: #fff; padding: 10px 16px; border-radius: var(--radius-s); font-size: 14px; transition: all .25s; pointer-events: none; }
  .toast.show { opacity: 1; transform: translate(-50%, 0); }
  .err { color: var(--fail); }

  @media (prefers-reduced-motion: reduce) { .chip { transition: none; } .chip.working { animation: none; } .toast { transition: none; } }
</style>
</head>
<body>
