<script>
const API_URL = "__API_URL__";
// ---- Loopwell shared helpers (inlined into each Code node that needs them) ----
// Who the emails come from. build.py also writes this name into every prompt.
const SENDER = 'Jayden';
// LLM chain nodes return {text: "..."} or, when the model answers in JSON mode, the parsed object itself.
function llmOut(item) {
  const j = (item && item.json) || {};
  if (typeof j.text === 'string' && Object.keys(j).length === 1) return parseJSON(j.text);
  if (j.output !== undefined) return parseJSON(j.output);
  return Object.keys(j).length ? j : null;
}

function parseJSON(text) {
  if (text === null || text === undefined) return null;
  if (typeof text === 'object') return text;
  let s = String(text).trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  const candidates = [s];
  if (a >= 0 && b > a) candidates.push(s.slice(a, b + 1));
  for (const c of candidates) { try { return JSON.parse(c); } catch (e) {} }
  for (const c of candidates) { try { return JSON.parse(repairJSON(c)); } catch (e) {} }
  return null;
}

// Models sometimes break JSON in two ways: a raw line break inside a string, or a stray
// unescaped quote mid-sentence (e.g. `\n"You'd made...`). Walk the text and escape both.
// A quote only closes a string when what follows is JSON structure (: , } ]), never prose.
const CLOSES_STRING = /\s*(?:[:}\]]|$|,\s*(?:"|\{|\[|\}|\]|-?\d|true\b|false\b|null\b))/y;
function repairJSON(s) {
  let out = '';
  let inStr = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (!inStr) { out += c; if (c === '"') inStr = true; continue; }
    if (c === '\\') { out += c + (s[i + 1] === undefined ? '' : s[i + 1]); i++; continue; }
    if (c === '\n') { out += '\\n'; continue; }
    if (c === '\r') continue;
    if (c === '\t') { out += '\\t'; continue; }
    if (c === '"') {
      CLOSES_STRING.lastIndex = i + 1;
      if (CLOSES_STRING.test(s)) { out += c; inStr = false; } else out += '\\"';
      continue;
    }
    out += c;
  }
  return out;
}

// True when a draft body is really a leaked JSON object instead of the email text.
function looksLikeJSON(body) {
  const b = String(body || '').trim();
  return /^[{[]/.test(b) || /"(subject|body|angle|notes)"\s*:/.test(b);
}

const BANNED = [
  'hope this finds you well', "hope you're well", 'hope you are well', 'circling back', 'circle back',
  'touching base', 'just checking in', 'i wanted to reach out', 'reaching out', 'quick question',
  'per my last email', 'hop on a call', 'pick your brain', 'synergy', 'leverage', 'game-changer',
  'game changer', 'ai-native', 'at your earliest convenience', 'no worries if not',
];

function firstName(n) { return String(n || '').trim().split(/\s+/)[0] || ''; }

function acctBrief(st) {
  return {
    company: st.company, contact_name: st.contact_name, contact_title: st.contact_title,
    timezone: st.timezone || null, deal_stage: st.deal_stage, loss_reason: st.loss_reason,
    loss_details: st.loss_details, close_date: st.close_date, original_ask: st.original_ask,
    call_notes: st.call_notes,
  };
}

function signalBrief(st) {
  const s = st.signal;
  if (!s || !s.verified) return null;
  return { signal: s.signal, type: s.type, evidence_quote: s.evidence_quote, source_title: s.source_title, source_date: s.source_date };
}

function normalizeDraft(d) {
  d = d || {};
  return {
    subject: String(d.subject || '').trim(),
    body: String(d.body || '').replace(/\r/g, '').replace(/\\n/g, '\n').replace(/\n{3,}/g, '\n\n')
      // A line with exactly one straight quote at its start or end is a leftover from broken JSON.
      .split('\n').map((l) => ((l.match(/"/g) || []).length === 1 ? l.replace(/^(\s*)"/, '$1').replace(/"(\s*)$/, '$1') : l)).join('\n')
      .trim(),
    angle: String(d.angle || ''),
    notes: Array.isArray(d.notes) ? d.notes.map(String) : [],
  };
}

function splitBody(body) {
  const nonEmpty = String(body || '').split('\n').map((l) => l.trim()).filter(Boolean);
  return { greeting: nonEmpty[0] || '', signoff: nonEmpty.length > 1 ? nonEmpty[nonEmpty.length - 1] : '', middle: nonEmpty.slice(1, -1) };
}

function checkDraft(cur, st) {
  const checks = [];
  const add = (id, label, ok, detail) => checks.push({ id, label, ok: !!ok, detail: ok ? '' : detail });
  const { greeting, signoff, middle } = splitBody(cur.body);
  const fn = firstName(st.contact_name);
  const text = middle.join(' ');
  const words = text.split(/\s+/).filter(Boolean).length;
  add('greeting', 'Greeting has no dash', /^(Hi [^,\-–—]+,|Hey [^,\-–—!.]+[!.])$/.test(greeting),
    `Greeting "${greeting}" must be "Hi ${fn}," or "Hey ${fn}!" with no dash.`);
  add('name', 'Uses their first name', fn && greeting.includes(fn), `Greeting should use "${fn}".`);
  const valediction = /^(best|thanks|thank you|cheers|regards|best regards|warmly|talk soon)[,!.]?$/i.test(middle[middle.length - 1] || '');
  add('signoff', `Signed just "${SENDER}"`, signoff === SENDER && !valediction, valediction ? `Drop "${middle[middle.length - 1]}". Sign off with just "${SENDER}".` : `Sign off with just "${SENDER}" (found "${signoff}").`);
  add('length', 'Under 90 words', words > 0 && words <= 90, `Body is ${words} words. Cut it to under 90.`);
  add('lines', '3 to 5 short lines', middle.length >= 3 && middle.length <= 5, `Body has ${middle.length} lines. Use 3 to 5 short lines.`);
  const excl = (cur.body.match(/!/g) || []).length;
  add('exclaim', 'At most 2 exclamation points', excl <= 2, `${excl} exclamation points. Use 2 at most.`);
  const hasEmoji = /\p{Extended_Pictographic}/u.test(cur.body);
  const hasMd = /(\*\*|__|^#|^\s*[-*•]\s)/m.test(cur.body) || /https?:\/\//i.test(cur.body);
  const leaked = looksLikeJSON(cur.body);
  add('plain', 'Plain text only', !hasEmoji && !hasMd && !leaked,
    leaked ? 'The draft came back as raw JSON. Rewrite it as the plain email body only.' : 'Remove emoji, markdown, bullets or links.');
  const lower = cur.body.toLowerCase();
  const hit = BANNED.filter((p) => lower.includes(p));
  add('banned', 'No banned phrases', hit.length === 0, `Remove banned phrase(s): ${hit.join(', ')}.`);
  const expectedSubject = `${st.company} <> Northfold`;
  add('subject', 'Subject is "Company <> Northfold"', cur.subject === expectedSubject, `Subject must be exactly "${expectedSubject}".`);
  const reason = String(st.loss_reason || '').toLowerCase();
  if (st.track === 'check-in') {
    const m = text.match(/\b(switch(ing)? back|instead of|better than|compared|other agency|their agency|pricing|price)\b/i);
    add('loss', 'Neutral about the competitor', !m, `Check-in track: drop "${m && m[0]}". No comparison and no pitch.`);
  } else if (/(budget|price)/.test(reason)) {
    const m = text.match(/\b(budget|budgets|price|pricing|cost|costs|discount|afford|spend)\b/i);
    add('loss', 'Budget loss not re-raised', !m, `This deal was lost on budget: don't mention "${m && m[0]}".`);
  } else {
    add('loss', 'Loss reason handled', true, '');
  }
  const allowed = [(st.signal && st.signal.evidence_quote) || '', st.call_notes || '', st.loss_details || '', st.original_ask || ''].join(' ');
  const nums = (text.match(/(?<![A-Za-z])\$?\d[\d,.]*%?/g) || [])
    .map((n) => n.replace(/[.,]$/, ''))
    .filter((n) => !/^20(2[5-9]|3\d)$/.test(n));
  const bad = nums.filter((n) => !allowed.includes(n));
  add('numbers', 'No invented numbers', bad.length === 0, `Number(s) not found in the evidence: ${bad.join(', ')}.`);
  const selfRefs = (text.match(/\b(we|we've|we're|our|us|northfold)\b/gi) || []).length;
  add('about', 'About them, not us', selfRefs <= 3, `${selfRefs} references to Northfold/we/our. Keep it about them.`);
  const last = middle[middle.length - 1] || '';
  const askOk = /\?\s*$/.test(last) && /(friday|fridays|next week|this week|catch up|catch-up|chat)/i.test(last);
  add('ask', 'Ends with a warm day-ask', askOk, 'Close with a warm, specific day-ask question, e.g. "Catch up one of these upcoming Fridays?"');
  if (st.timezone && /friday/i.test(last)) {
    add('tz', `Timezone labeled (${st.timezone})`, last.includes(st.timezone), `Label the Friday ask with their timezone (${st.timezone}).`);
  }
  add('no_calendly', 'No Calendly link', !/calendly/i.test(cur.body), 'Remove the Calendly mention.');
  const failures = checks.filter((c) => !c.ok).map((c) => c.detail);
  return { checks, failures, passed: checks.length - failures.length, total: checks.length, words, lines: middle.length };
}

function judgeInput(st, cur) {
  return JSON.stringify({ account: acctBrief(st), track: st.track, signal: signalBrief(st), draft: { subject: cur.subject, body: cur.body }, style_guide: st.style_guide || undefined });
}

function reviseInput(st, cur, ruleFailures, judgeFailures) {
  return JSON.stringify({
    account: acctBrief(st), track: st.track, signal: signalBrief(st), today: st.today, style_guide: st.style_guide || undefined,
    current_draft: { subject: cur.subject, body: cur.body },
    failures: [
      ...ruleFailures.map((d) => ({ check: 'rules', detail: d })),
      ...(judgeFailures || []).map((f) => ({ check: f.check || 'judge', detail: f.detail || String(f) })),
    ],
  });
}

// ---- Fact check: a claim counts as verified only if code finds the claim in the draft AND the
// quoted evidence in the source it cites. The model proposes; code decides.
const FACT_SOURCES = {
  crm_call_notes: 'CRM call notes',
  crm_loss_details: 'CRM loss details',
  crm_original_ask: 'CRM original ask',
  crm_loss_reason: 'CRM loss reason',
  crm_deal: 'CRM deal record',
};

function factSources(st) {
  const src = {
    crm_call_notes: st.call_notes || '',
    crm_loss_details: st.loss_details || '',
    crm_original_ask: st.original_ask || '',
    crm_loss_reason: st.loss_reason || '',
    crm_deal: `Deal stage: ${st.deal_stage || ''}. Closed: ${st.close_date || ''}. Contact: ${st.contact_name || ''}, ${st.contact_title || ''}.`,
  };
  if (st.signal && st.signal.verified) src.web_signal = st.signal.evidence_quote || '';
  return src;
}

function normText(t) {
  return String(t || '').toLowerCase()
    .replace(/[‘’‛`´]/g, "'").replace(/[“”„]/g, '"').replace(/[–—]/g, '-')
    .replace(/[^a-z0-9'%$ ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

// Is `needle` in `hay`, ignoring case, punctuation and spacing? For longer quotes, a copy slip of a word
// or two is tolerated: 90% of the needle's words must appear in order within a short window.
function foundIn(needle, hay) {
  const n = normText(needle);
  const h = normText(hay);
  if (!n || !h) return false;
  if (h.includes(n)) return true;
  const nw = n.split(' ');
  const hw = h.split(' ');
  if (nw.length < 5) return false;
  let best = 0;
  for (let s = 0; s < hw.length && best < nw.length; s++) {
    if (hw[s] !== nw[0] && hw[s] !== nw[1]) continue;
    let j = 0;
    let matched = 0;
    for (let k = s; k < hw.length && j < nw.length && k < s + nw.length + 4; k++) {
      if (hw[k] === nw[j]) { matched++; j++; }
      else if (j + 1 < nw.length && hw[k] === nw[j + 1]) { matched++; j += 2; } // needle word j is missing here
    }
    best = Math.max(best, matched);
  }
  return best / nw.length >= 0.9;
}

function verifyClaims(raw, st, body) {
  const src = factSources(st);
  const sig = st.signal && st.signal.verified ? st.signal : null;
  const list = raw && Array.isArray(raw.claims) ? raw.claims : null;
  if (!list) return { claims: [], verified: 0, total: 0, error: 'The fact checker could not run on this draft.' };
  const claims = [];
  for (const c of list.slice(0, 8)) {
    const draft_quote = String((c && c.draft_quote) || '').trim();
    const claim = String((c && c.claim) || '').trim();
    if (!claim || !draft_quote || !foundIn(draft_quote, body)) continue; // the checker may not invent text
    if (/^(hi|hey|hello) [a-z'-]+$/.test(normText(draft_quote))) continue; // the greeting is not a fact
    const id = String(c.source || 'none');
    const evidence = String(c.evidence || '').trim();
    let status = 'verified';
    let why = '';
    if (id === 'none' || !(id in src)) { status = 'unsupported'; why = 'No source in the CRM or on the web says this.'; }
    else if (!evidence || !foundIn(evidence, src[id])) { status = 'unsupported'; why = `The quoted evidence is not in the ${id === 'web_signal' ? 'web source' : FACT_SOURCES[id]}.`; }
    const source = id === 'web_signal' && sig
      ? { id, kind: 'web', label: sig.source_type === 'homepage' ? 'Their homepage' : 'News', title: sig.source_title || '', url: sig.source_url || '', date: sig.source_date || '' }
      : FACT_SOURCES[id]
        ? { id, kind: 'crm', label: FACT_SOURCES[id], title: '', url: '', date: id === 'crm_deal' ? st.close_date || '' : '' }
        : { id: 'none', kind: 'none', label: 'No source', title: '', url: '', date: '' };
    claims.push({ claim, draft_quote, source, evidence: status === 'verified' ? evidence : '', status, why, at: normText(body).indexOf(normText(draft_quote)) });
  }
  // Number the facts in reading order, so marker 1 is the first fact in the email.
  claims.sort((x, y) => (x.at < 0) - (y.at < 0) || x.at - y.at);
  claims.forEach((c, i) => { c.n = i + 1; delete c.at; });
  return { claims, verified: claims.filter((c) => c.status === 'verified').length, total: claims.length };
}

function scoreOf(judgeScore, ruleFailureCount) {
  const j = Number.isFinite(Number(judgeScore)) ? Number(judgeScore) : 5;
  return Math.max(0, Math.min(10, Math.round((j - ruleFailureCount) * 10) / 10));
}
// ---- end helpers ----


const STATIONS = [
  { key: 'queued', name: 'Queued', x: 6 },
  { key: 'research', name: 'Research', x: 20.8 },
  { key: 'draft', name: 'Draft', x: 35.6 },
  { key: 'quality', name: 'Quality check', x: 50.4 },
  { key: 'review', name: 'Your review', x: 65.2 },
  { key: 'gmail', name: 'Sent', x: 80 },
  { key: 'aside', name: 'Set aside', x: 93, aside: true },
];
const STATUS = {
  queued:            { label: 'Queued', station: 'queued', tone: 'off' },
  researching:       { label: 'Researching', station: 'research', tone: 'working' },
  drafting:          { label: 'Drafting', station: 'draft', tone: 'working' },
  reviewing:         { label: 'Checking quality', station: 'quality', tone: 'working' },
  awaiting_approval: { label: 'Ready for your review', station: 'review', tone: 'waiting' },
  sent:              { label: 'Sent', station: 'gmail', tone: 'done' },
  in_gmail:          { label: 'Draft in Gmail', station: 'gmail', tone: 'done' },
  rejected:          { label: 'Rejected', station: 'review', tone: 'bad' },
  cooling_down:      { label: 'Cooling down', station: 'aside', tone: 'off' },
  cleaned_up:        { label: 'Cleaned up', station: 'aside', tone: 'off' },
  expired:           { label: 'Out of window', station: 'aside', tone: 'off' },
  needs_review:      { label: `Needs ${SENDER}`, station: 'aside', tone: 'bad' },
  fact_checking:     { label: 'Checking facts', station: 'quality', tone: 'working' },
};
const TRACKS = { standard: 'Standard', 'check-in': 'Competitor check-in', 'win-back': 'Win-back', cleanup: 'Cleanup', flag: 'Flagged' };
const ACTIVE = ['researching', 'drafting', 'reviewing', 'fact_checking'];

let state = { accounts: [], selected: null, editing: false, loaded: false, needsSetup: false, busy: false };
let pollTimer = null, fastUntil = 0;

const $ = (s) => document.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const initials = (name) => String(name || '?').replace(/\(.*\)/, '').trim().split(/\s+/).slice(0, 2).map((w) => w[0]).join('').toUpperCase();
const st = (a) => STATUS[a.status] || { label: a.status || 'Unknown', station: 'queued', tone: 'off' };
const ICON_OK = '<svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><path d="M2.5 7.5l3 3 6-7" fill="none" stroke="#17805A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const ICON_NO = '<svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><path d="M3 3l8 8M11 3l-8 8" fill="none" stroke="#B8342B" stroke-width="2" stroke-linecap="round"/></svg>';

function toast(msg) { const t = $('#toast'); t.textContent = msg; t.classList.add('show'); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('show'), Math.max(2600, String(msg).length * 55)); }

async function api(action, data = {}) {
  const f = typeof flowBegin === 'function' ? flowBegin(action) : null;
  let r = null;
  try {
    const res = await fetch(API_URL, { method: 'POST', body: new URLSearchParams({ action, ...data }) });
    const txt = await res.text();
    try { r = JSON.parse(txt); } catch (e) { throw new Error(`The API answered with status ${res.status}. Check that the Loopwell workflow is published.`); }
    return r;
  } finally { if (f) flowEnd(f, action, r); }
}

// Viewing is open. Every change sends the passcode, asked once per page load and kept only in memory.
let PASS = '';
const ask = $('#ask');
function askDialog({ title, text, okLabel, okClass = 'primary', needPass, error }) {
  return new Promise((resolve) => {
    $('#askTitle').textContent = title;
    $('#askText').innerHTML = text || '';
    $('#askText').style.display = text ? '' : 'none';
    $('#askPassWrap').style.display = needPass ? '' : 'none';
    $('#askPass').value = '';
    $('#askErr').textContent = error || '';
    const ok = $('#askOk'); ok.textContent = okLabel; ok.className = `btn ${okClass}`;
    const done = (val) => { ask.close(); ok.onclick = null; $('#askCancel').onclick = null; $('#askPass').onkeydown = null; ask.oncancel = null; resolve(val); };
    const submit = () => {
      const pass = $('#askPass').value.trim();
      if (needPass && !pass) { $('#askErr').textContent = 'Enter the passcode.'; $('#askPass').focus(); return; }
      done({ pass });
    };
    ok.onclick = submit;
    $('#askCancel').onclick = () => done(null);
    $('#askPass').onkeydown = (e) => { if (e.key === 'Enter') { e.preventDefault(); submit(); } };
    ask.oncancel = (e) => { e.preventDefault(); done(null); };
    ask.showModal();
    (needPass ? $('#askPass') : ok).focus();
  });
}

// Runs a write action. Shows the dialog when a confirmation is wanted or the passcode isn't known yet,
// and asks again if the server says the passcode is wrong. Returns null if the person cancels.
async function act(action, data, dlg) {
  let confirmFirst = !!(dlg && dlg.confirm);
  let error = '';
  for (;;) {
    if (confirmFirst || !PASS) {
      const base = dlg || { title: 'Enter the passcode', okLabel: 'Continue' };
      const res = await askDialog({ ...base, needPass: !PASS, error });
      if (!res) return null;
      if (res.pass) PASS = res.pass;
      confirmFirst = false;
    }
    const r = await api(action, { ...data, passcode: PASS });
    if (r && r.error === 'passcode') { PASS = ''; error = r.message; confirmFirst = true; dlg = dlg || null; continue; }
    return r;
  }
}

function setLive(ok, text) { $('#live').classList.toggle('on', ok); $('#liveText').textContent = text; }

async function refresh() {
  try {
    const data = await api('list');
    state.needsSetup = !!data.needs_setup;
    state.style = data.style || null;
    state.learned = data.learned || null;
    announceLearned();
    state.watcher = data.watcher || null;
    const nRules = ((state.learned || {}).rules || []).length;
    $('#btnStyle').innerHTML = 'Writing style' + (state.style ? '<span class="tag">Custom</span>' : '') + (nRules ? `<span class="tag">${nRules} learned</span>` : '');
    $('#btnStyle').title = state.style ? `Drafts follow ${state.style.name}` : 'Drafts use the default house style';
    // The CRM is the loopwell_accounts Data Table. Without a saved link, open n8n's Data tables list.
    $('#btnCrm').href = data.crm_url || API_URL.replace(/\/webhook\/.*$/, '') + '/home/datatables';
    state.accounts = data.accounts || [];
    state.loaded = true;
    trackChanges();
    if (!state.selected || !state.accounts.find((a) => a.account_id === state.selected)) {
      const pick = state.accounts.find((a) => a.qa) || state.accounts[0];
      state.selected = pick ? pick.account_id : null;
    }
    const active = state.accounts.some((a) => ACTIVE.includes(a.status));
    setLive(true, active ? 'Pipeline running' : 'Live');
    render();
  } catch (e) {
    setLive(false, 'Offline');
    if (!state.loaded) { $('#list').innerHTML = ''; $('#detail').innerHTML = `<div class="panel empty"><h2>Can't reach the Loopwell API</h2><p class="err">${esc(e.message)}</p><button class="btn" type="button" onclick="refresh()">Try again</button></div>`; }
  }
  schedule();
}

function schedule() {
  clearTimeout(pollTimer);
  if (document.hidden) return;
  const active = state.accounts.some((a) => ACTIVE.includes(a.status));
  const waiting = state.accounts.some((a) => a.status === 'awaiting_approval');
  const ms = active || Date.now() < fastUntil ? 2500 : waiting ? 8000 : 20000;
  pollTimer = setTimeout(refresh, ms);
}
document.addEventListener('visibilitychange', () => { if (!document.hidden) refresh(); });

function render() { renderLoop(); renderList(); if (!state.editing) renderDetail(); updateFlow(); }

function renderLoop() {
  const loop = $('#loop');
  if (!loop.dataset.built) {
    STATIONS.forEach((s) => {
      const el = document.createElement('div');
      el.className = 'station' + (s.aside ? ' aside' : '');
      el.style.left = s.x + '%';
      el.innerHTML = `<div class="name">${s.name}</div><div class="dot"></div><div class="count" data-count="${s.key}"></div>`;
      loop.appendChild(el);
    });
    loop.dataset.built = '1';
  }
  const width = loop.clientWidth;
  const stacks = {};
  const seen = new Set();
  state.accounts.forEach((a) => {
    const s = st(a);
    const station = STATIONS.find((x) => x.key === s.station) || STATIONS[0];
    const idx = (stacks[station.key] = (stacks[station.key] || 0) + 1) - 1;
    const col = idx % 3, rowN = Math.floor(idx / 3);
    const x = (station.x / 100) * width - 15 + (col - 1) * 33;
    const y = 76 + rowN * 34;
    let chip = loop.querySelector(`.chip[data-id="${a.account_id}"]`);
    if (!chip) {
      chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'chip';
      chip.dataset.id = a.account_id;
      chip.style.transform = `translate(${(STATIONS[0].x / 100) * width - 15}px, ${y}px)`;
      chip.addEventListener('click', () => select(a.account_id));
      loop.appendChild(chip);
      chip.getBoundingClientRect();
    }
    chip.textContent = initials(a.company);
    chip.title = `${a.company}: ${s.label}`;
    chip.setAttribute('aria-label', `${a.company}, ${s.label}`);
    chip.className = `chip ${s.tone}${state.selected === a.account_id ? ' sel' : ''}`;
    chip.style.transform = `translate(${x}px, ${y}px)`;
    seen.add(a.account_id);
  });
  loop.querySelectorAll('.chip').forEach((c) => { if (!seen.has(c.dataset.id)) c.remove(); });
  const rows = Math.max(1, ...Object.values(stacks).map((n) => Math.ceil(n / 3)));
  loop.style.height = 76 + rows * 34 + 8 + 'px';
  STATIONS.forEach((s) => { const n = stacks[s.key] || 0; const el = loop.querySelector(`[data-count="${s.key}"]`); if (el) el.textContent = n ? `${n} account${n === 1 ? '' : 's'}` : ''; });
}

function renderList() {
  const list = $('#list');
  if (state.needsSetup) { list.innerHTML = ''; return; }
  const drafted = state.accounts.filter((a) => a.draft_body).length;
  const w = state.watcher || {};
  const when = w.last_check ? new Date(w.last_check) : null;
  const watchText = when
    ? `The watcher checked ${w.watching} site${w.watching === 1 ? '' : 's'} ${when.toDateString() === new Date().toDateString() ? 'today' : 'on ' + when.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} at ${when.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}. It checks again every morning.`
    : 'The watcher checks each open account every morning for homepage changes and fresh news. Click Check for new signals to run it now.';
  list.innerHTML = `<h2><span>Accounts</span><span>${drafted} of ${state.accounts.length} drafted</span></h2><div class="watchline">${esc(watchText)}</div>` +
    state.accounts.map((a) => {
      const s = st(a);
      const score = a.qa && a.qa.final_score != null ? `${Number(a.qa.final_score).toFixed(1).replace('.0', '')}<small>/10</small>` : '';
      return `<button type="button" class="row${state.selected === a.account_id ? ' sel' : ''}" data-id="${esc(a.account_id)}">
        <span class="co">${esc(a.company)}${isNew(a) ? '<span class="newtag">New signal</span>' : ''}</span>
        <span class="score">${score}</span>
        <span class="meta">${esc(a.contact_name)}${a.track ? ', ' + esc(TRACKS[a.track] || a.track) : ''}<br><span class="state s-${s.tone}">${esc(s.label)}</span></span>
      </button>`;
    }).join('');
  list.querySelectorAll('.row').forEach((r) => r.addEventListener('click', () => select(r.dataset.id)));
}

// An account counts as "New signal" for 3 days after the watcher spots a change.
function isNew(a) { const w = a.watch; return !!(w && w.changed_at && (w.changes || []).length && Date.now() - new Date(w.changed_at).getTime() < 3 * 864e5); }

function changesHtml(a) {
  const w = a.watch;
  if (!w || !(w.changes || []).length || !w.changed_at) return '';
  const items = w.changes.map((c) => {
    const where = c.type === 'news' ? `News${c.source ? ': ' + esc(c.source) : ''}${c.date ? ', ' + esc(fmtDate(c.date)) : ''}` : `Their homepage, spotted ${esc(fmtDate(String(w.changed_at).slice(0, 10)))}`;
    return `<li>${ICON_WEB}<div><div class="what">${esc(c.text)}</div><div class="where">${where}${c.url ? `, <a href="${esc(c.url)}" target="_blank" rel="noopener">Open</a>` : ''}</div></div></li>`;
  }).join('');
  return `<section class="panel"><h3>What's new since the last check</h3><ul class="changes">${items}</ul></section>`;
}

function select(id) { state.selected = id; state.editing = false; render(); }

function checksHtml(checks) {
  return `<ul class="checks">${(checks || []).map((c) => `<li class="${c.ok ? 'ok' : 'no'}">${c.ok ? ICON_OK : ICON_NO}<span>${esc(c.label)}${c.ok ? '' : `<span class="d">${esc(c.detail)}</span>`}</span></li>`).join('')}</ul>`;
}

// Same-length folding (1:1 characters), so an index found in the folded text is valid in the original.
const fold = (t) => String(t || '').toLowerCase().replace(/[‘’‛]/g, "'").replace(/[“”„]/g, '"').replace(/[–—]/g, '-');
const fmtDate = (d) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d || ''); return m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }) : (d || ''); };
const ICON_WEB = '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><circle cx="7" cy="7" r="5.6" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M1.6 7h10.8M7 1.4c-2 2.2-2 9 0 11.2M7 1.4c2 2.2 2 9 0 11.2" fill="none" stroke="currentColor" stroke-width="1.2"/></svg>';
const ICON_CRM = '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><ellipse cx="7" cy="3.4" rx="5" ry="1.9" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M2 3.4v7.2c0 1 2.2 1.9 5 1.9s5-.9 5-1.9V3.4M2 7c0 1 2.2 1.9 5 1.9S12 8 12 7" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>';

// Claims for the current draft text: a claim whose wording was edited out is marked stale, not verified.
function draftFacts(a) {
  const f = (a.qa || {}).facts;
  if (!f) return null;
  const body = fold(a.draft_body);
  const claims = (f.claims || [])
    .filter((c) => !/^(hi|hey|hello) [^\s,!]+[,!]?$/.test(fold(c.draft_quote).trim()))
    .map((c) => { const at = body.indexOf(fold(c.draft_quote)); return { ...c, at, stale: at < 0 }; })
    .sort((x, y) => (x.stale - y.stale) || (x.at - y.at))
    .map((c, i) => ({ ...c, n: i + 1 }));
  return { ...f, claims, unsupported: claims.filter((c) => !c.stale && c.status !== 'verified').length,
    verifiedNow: claims.filter((c) => !c.stale && c.status === 'verified').length, staleCount: claims.filter((c) => c.stale).length };
}

function letterHtml(a, facts) {
  const body = String(a.draft_body || '');
  const spans = [];
  (facts ? facts.claims : []).filter((c) => !c.stale).sort((x, y) => x.at - y.at).forEach((c) => {
    const end = c.at + c.draft_quote.length;
    if (!spans.length || c.at >= spans[spans.length - 1].end) spans.push({ start: c.at, end, n: c.n, bad: c.status !== 'verified' });
  });
  let out = '', pos = 0;
  spans.forEach((s) => {
    out += esc(body.slice(pos, s.start)) + `<span class="cite${s.bad ? ' bad' : ''}" data-n="${s.n}">${esc(body.slice(s.start, s.end))}</span><sup class="fn${s.bad ? ' bad' : ''}">${s.n}</sup>`;
    pos = s.end;
  });
  return out + esc(body.slice(pos));
}

function factsHtml(a, facts) {
  if (ACTIVE.includes(a.status)) return `<aside class="facts"><h3>Facts in this draft</h3><p class="none">${esc(st(a).label)}. Each fact is checked against its source as soon as the quality passes finish.</p></aside>`;
  if (!facts) return `<aside class="facts"><h3>Facts in this draft</h3><p class="none">Facts and their sources appear here after the next run.</p></aside>`;
  if (facts.error) return `<aside class="facts"><h3>Facts in this draft</h3><p class="none err">${esc(facts.error)} Check the claims yourself before sending.</p></aside>`;
  if (!facts.claims.length) return `<aside class="facts"><h3>Facts in this draft</h3><p class="none">This draft makes no factual claims about them.</p></aside>`;
  const live = facts.claims.length - facts.staleCount;
  const tally = facts.unsupported
    ? `<span class="tally bad">${facts.unsupported} of ${live} not backed by a source</span>`
    : `<span class="tally">${facts.verifiedNow} of ${live} verified</span>`;
  const items = facts.claims.map((c) => {
    const cls = c.stale ? 'stale' : c.status === 'verified' ? 'ok' : 'bad';
    const s = c.source || {};
    const when = [s.date ? (s.kind === 'web' ? 'Read ' : 'Closed ') + esc(fmtDate(s.date)) : '', s.url ? `<a href="${esc(s.url)}" target="_blank" rel="noopener">Open source</a>` : ''].filter(Boolean).join(', ');
    const src = s.kind === 'none' ? '' : `<div class="fsrc">${s.kind === 'web' ? ICON_WEB : ICON_CRM}<div>${esc(s.label)}${s.title && s.kind === 'web' ? ': ' + esc(s.title) : ''}${when ? `<br>${when}` : ''}</div></div>`;
    const evi = c.evidence && !c.stale ? `<blockquote class="evi">${esc(c.evidence)}</blockquote>` : '';
    const stat = c.stale ? 'You edited this line, so it was not re-checked.'
      : c.status === 'verified' ? `${ICON_OK} Found word-for-word in the source` : `${ICON_NO} ${esc(c.why || 'Not found in any source.')}`;
    return `<li class="fact ${cls}" data-n="${c.n}"><span class="num">${c.n}</span><div><p class="claim">${esc(c.claim)}</p>${src}${evi}<div class="fstat">${stat}</div></div></li>`;
  }).join('');
  return `<aside class="facts" aria-label="Facts in this draft"><h3>Facts in this draft</h3>${tally}<ol class="fact-list">${items}</ol></aside>`;
}

// Hovering a fact highlights its words in the email, and the other way around.
function linkFacts(root) {
  const hot = (n, on) => root.querySelectorAll(`[data-n="${n}"]`).forEach((el) => el.classList.toggle('hot', on));
  root.querySelectorAll('.cite, .fact').forEach((el) => {
    el.addEventListener('mouseenter', () => hot(el.dataset.n, true));
    el.addEventListener('mouseleave', () => hot(el.dataset.n, false));
  });
}

// Bold the label at the start of a note ("Loss reason:", "Contact:", "Opener signal:") so the list scans fast.
function noteHtml(n) {
  const s = String(n || '').replace(/^Day-ask uses /, 'Day-ask: uses ');
  const m = /^([A-Z][A-Za-z0-9 ,'-]{1,38}):\s+([\s\S]*)$/.exec(s);
  return m ? `<b>${esc(m[1])}:</b> ${esc(m[2])}` : esc(s);
}

function renderDetail() {
  const d = $('#detail');
  if (state.needsSetup) {
    d.innerHTML = `<div class="panel empty"><h2>No CRM loaded yet</h2><p>Load the demo CRM to create the accounts table and fill it with eight sample closed-lost and former-customer accounts.</p><button class="btn primary" type="button" id="btnSetup">Load demo CRM</button></div>`;
    $('#btnSetup').addEventListener('click', loadDemo);
    return;
  }
  const a = state.accounts.find((x) => x.account_id === state.selected);
  if (!a) { d.innerHTML = ''; return; }
  const s = st(a);
  const qa = a.qa || {};
  const research = a.research || {};
  const sig = research.signal || null;
  const parts = [];

  parts.push(`<section class="panel"><div class="who"><div><h2>${esc(a.company)}</h2>
    <p>${esc(a.contact_name)}${a.contact_title ? ', ' + esc(a.contact_title) : ''}${a.timezone ? ' (' + esc(a.timezone) + ')' : ''}</p>
    <p>${esc(a.contact_email)}${a.demo ? `<span class="demo-tag" title="${esc(a.send_to ? `Made-up demo contact. Approve & send delivers to your inbox, ${a.send_to}, never to this address.` : 'Made-up demo contact. Add a demo_inbox row to loopwell_settings so Approve & send can deliver it to your inbox.')}">Demo contact</span>` : ''}</p></div>
    <div><span class="pill ${s.tone}">${esc(s.label)}</span></div></div>
    <div class="why"><b>${esc(TRACKS[a.track] || 'Not triaged yet')}.</b> ${esc(a.triage_note || 'Run a batch to triage this account.')}
    ${a.loss_reason ? `<br><span style="color:var(--muted)">Lost ${esc(a.close_date)}: ${esc(a.loss_reason)}. ${esc(a.loss_details)}</span>` : ''}</div></section>`);

  const news = changesHtml(a);
  if (news) parts.push(news);

  if (a.draft_body) {
    const facts = draftFacts(a);
    const running = ACTIVE.includes(a.status);
    parts.push(`<section class="panel"><div class="draft-grid"><div><h3>${running ? 'Draft in progress' : `Draft for ${SENDER}`}</h3>
      <div class="letter"><div class="subj">Subject: <b>${esc(a.draft_subject)}</b></div><div class="body">${letterHtml(a, facts)}</div></div>
      <div class="letter-actions">
        ${running ? `<span class="pending"><i></i>Still checking. Approve &amp; send appears when the quality and fact checks finish.</span>` : ''}
        ${['awaiting_approval', 'rejected'].includes(a.status) ? `<button class="btn send" type="button" id="btnSend">Approve &amp; send</button>` : ''}
        ${a.status === 'awaiting_approval' ? `<button class="btn reject" type="button" id="btnReject">Reject</button>` : ''}
        ${['awaiting_approval', 'rejected'].includes(a.status) ? `<button class="btn" type="button" id="btnEdit">Edit draft</button>` : ''}
        ${ACTIVE.includes(a.status) || ['sent', 'in_gmail'].includes(a.status) ? '' : `<button class="btn quiet" type="button" id="btnRedo">Redo this account</button>`}
        ${a.status === 'sent' ? `<span class="sent-note">Sent to ${esc(a.demo ? 'your inbox, ' + a.send_to : a.contact_email)}</span><a class="btn quiet" href="https://mail.google.com/mail/u/0/#sent" target="_blank" rel="noopener">Open Gmail Sent</a>` : ''}
        ${a.status === 'in_gmail' ? `<a class="btn quiet" href="https://mail.google.com/mail/u/0/#drafts" target="_blank" rel="noopener">Open Gmail drafts</a>` : ''}
        ${a.edited ? `<span class="edited">Edited by ${SENDER}. Approve &amp; send uses this version.</span>` : ''}
      </div></div>${factsHtml(a, facts)}</div></section>`);
  } else if (ACTIVE.includes(a.status)) {
    parts.push(`<section class="panel"><h3>Draft for ${SENDER}</h3><p style="color:var(--muted);margin:0">${esc(s.label)}. The draft appears here as soon as the drafting agent finishes.</p></section>`);
  }

  if (sig) {
    if (sig.verified) {
      parts.push(`<section class="panel"><h3>Opener signal</h3><p style="margin:0 0 10px">${esc(sig.signal)}</p>
        <blockquote class="quote">${esc(sig.evidence_quote)}</blockquote>
        <div class="src">${esc(sig.source_type === 'homepage' ? 'Their homepage, read today' : sig.source_title)}${sig.source_date ? ', ' + esc(sig.source_date) : ''}${sig.source_url ? ` · <a href="${esc(sig.source_url)}" target="_blank" rel="noopener">Open source</a>` : ''}</div>
        <div class="verified">${ICON_OK} Quote verified word-for-word in the source</div>
        ${sig.why_it_matters ? `<p style="margin:10px 0 0;color:var(--muted)">${esc(sig.why_it_matters)}</p>` : ''}</section>`);
    } else {
      const n = (research.sources || []).length;
      parts.push(`<section class="panel"><h3>Opener signal</h3><p class="rejected">${esc(sig.rejected_reason || 'No signal used.')}</p><div class="src">Read ${n} source${n === 1 ? '' : 's'}: homepage ${esc((research.fetch || {}).homepage || 'n/a')}, ${esc((research.fetch || {}).news_items ?? 0)} recent news items.</div></section>`);
    }
  }

  if (qa.versions && qa.versions.length) {
    const passes = qa.versions.map((v, i) => {
      const chosen = (qa.chosen_version || qa.versions.length) === v.v;
      const ok = chosen && qa.passed;
      const fixes = [...(v.rule_failures || []), ...((v.judge_failures || []).map((f) => f.detail || f))];
      return `<div class="pass${ok ? ' ok' : ''}"><div class="n">Draft ${v.v}${chosen && qa.versions.length > 1 ? `, the one ${SENDER} gets` : ''}</div><div class="sc">${v.score != null ? v.score : '–'}<small>/10</small></div>
