  }

  d.innerHTML = parts.join('');
  linkFacts(d);
  const be = $('#btnEdit'); if (be) be.addEventListener('click', () => openEditor(a));
  const br = $('#btnRedo'); if (br) br.addEventListener('click', () => runBatch(a.account_id));
  const bs = $('#btnSend'); if (bs) bs.addEventListener('click', () => decide(a, 'approve'));
  const bj = $('#btnReject'); if (bj) bj.addEventListener('click', () => decide(a, 'reject'));
}

async function decide(a, which) {
  const send = which === 'approve';
  const dlg = send
    ? { confirm: true, title: `Send to ${a.contact_name}?`, okLabel: 'Send email', okClass: 'send',
        text: (a.demo
          ? `${esc(a.contact_name)} is a made-up demo contact, so this emails the draft from your Gmail to your own inbox, <span class="to">${esc(a.send_to || 'no demo inbox set')}</span>, not to ${esc(a.contact_email)}. It can't be unsent.`
          : `This emails the draft from your Gmail to <span class="to">${esc(a.contact_email)}</span>. It can't be unsent.`) +
          (((f) => f && f.unsupported ? `<br><span class="warn">${f.unsupported} fact${f.unsupported === 1 ? ' isn\'t' : 's aren\'t'} backed by a source. Check ${f.unsupported === 1 ? 'it' : 'them'} first.</span>` : '')(draftFacts(a))) }
    : { confirm: true, title: `Reject the ${a.company} draft?`, okLabel: 'Reject draft', okClass: 'primary',
        text: 'Nothing is sent. You can still edit it and approve it later.' };
  const btns = ['#btnSend', '#btnReject', '#btnEdit'].map((s) => $(s)).filter(Boolean);
  btns.forEach((b) => (b.disabled = true));
  try {
    const r = await act(which, { account_id: a.account_id }, dlg);
    if (!r) return;
    toast(r.message || (r.ok ? 'Done' : 'Something went wrong'));
    await refresh();
  } catch (e) { toast(e.message); }
  finally { btns.forEach((b) => (b.disabled = false)); }
}

function openEditor(a) {
  state.editing = true;
  const d = $('#detail');
  d.innerHTML = `<section class="panel editor"><h3>Edit draft for ${esc(a.company)}</h3>
    <label for="edSubj">Subject</label><input id="edSubj" value="${esc(a.draft_subject)}">
