    const r = await act('run', accountId ? { account_id: accountId } : {}, { title: 'Passcode needed', text: 'Changes on the desk need the passcode.', okLabel: accountId ? 'Redo account' : 'Run batch' });
    if (!r) return;
    fastUntil = Date.now() + 4 * 60 * 1000;
    toast(accountId ? 'Redoing this account' : 'Batch started');
    setTimeout(refresh, 900);
  } catch (e) { toast(e.message); }
  finally { setTimeout(() => (btn.disabled = false), 2500); }
}

async function loadDemo() {
  const dlg = state.accounts.length
    ? { confirm: true, title: 'Reload the demo CRM?', okLabel: 'Reload', text: 'This clears every draft and status.' } : null;
