  if (x2 >= x1 + 30) { const dx = Math.max(50, (x2 - x1) / 2); return `M${x1} ${y1}C${x1 + dx} ${y1} ${x2 - dx} ${y2} ${x2} ${y2}`; }
  const ych = B.y > A.y + A.h ? (A.y + A.h + B.y) / 2 : B.y + B.h < A.y ? (B.y + B.h + A.y) / 2 : Math.max(A.y + A.h, B.y + B.h) + 40;
  return `M${x1} ${y1}C${x1 + 70} ${y1} ${x1 + 70} ${ych} ${x1} ${ych}L${x2} ${ych}C${x2 - 70} ${ych} ${x2 - 70} ${y2} ${x2} ${y2}`;
}
function aiD(m, t) {
  const M = N[m], T = N[t];
  return `M${M.x + 50} ${M.y}C${M.x + 50} ${M.y - 180} ${T.x + 50} ${T.y + T.h + 180} ${T.x + 50} ${T.y + T.h}`;
}
function nodeSvg(n) {
