    : `<rect class="halo" x="-16" y="-16" width="132" height="${n.h + 32}" rx="30"/>` + (['webhook', 'schedule'].includes(n.kind)
      ? '<path class="b" d="M46 0H86A14 14 0 0 1 100 14V86A14 14 0 0 1 86 100H46A46 46 0 0 1 0 54V46A46 46 0 0 1 46 0Z"/>'
