}

function buildFlow() {
  if (flow.built) return;
  const svg = $('#flowSvg');
  svg.innerHTML = `<g id="flowWorld">
    <g>${GRAPH.sections.map((s) => `<g class="sec" data-s="${s.id}" style="--h:${HUE[s.id]}"><rect x="${s.x}" y="${s.y}" width="${s.w}" height="${s.h}" rx="28"/></g>`).join('')}</g>
    <g>${GRAPH.ai.map(([m, t], i) => `<path class="ga" data-e="${i}" d="${aiD(m, t)}" style="--h:${HUE[N[t].sec]}"/>`).join('')}</g>
    <g>${GRAPH.edges.map(([a, oi, b], i) => `<path class="ge" id="fe${i}" data-e="${i}" d="${edgeD(a, oi, b)}" style="--h:${HUE[N[b].sec]}"/>`).join('')}</g>
    <g id="flowPk"></g>
    <g>${N.map(nodeSvg).join('')}</g></g>`;
  flow.len = GRAPH.edges.map((e, i) => { try { return $('#fe' + i).getTotalLength(); } catch (err) { return 300; } });
  const ov = $('#flowOv');
  ov.innerHTML = GRAPH.sections.map((s) => `<button type="button" class="sl" data-s="${s.id}" style="--h:${HUE[s.id]}" title="Zoom to ${esc(s.title)}"><span class="t">${esc(s.title)}</span><span class="bd" data-bd="${s.id}"></span></button>`).join('')
    + N.map((n) => `<span class="nl" data-n="${n.i}">${esc(n.name)}</span>`).join('') + '<div class="tip" id="flowTip" hidden></div>';
  ov.querySelectorAll('.sl').forEach((b) => b.addEventListener('click', () => { setFollow(false); viewTo(sectionRect([+b.dataset.s]), true); }));
  wireCanvas();
  if ($('#canvas').clientWidth < 620) { $('#flowFeed').classList.add('closed'); $('#feedToggle').setAttribute('aria-expanded', 'false'); }
  $('#flowOpen').href = WORKFLOW_URL;
  flow.built = true;
}

// ---- Camera
const canvasSize = () => { const c = $('#canvas'); return { W: c.clientWidth, H: c.clientHeight }; };
function sectionRect(ids) {
  const rs = ids.map((id) => { const s = SEC[id]; return STAGE_NAME[id] ? { x: s.x, y: s.y - 200, w: s.w, h: s.h + 200 } : s; });
  const x = Math.min(...rs.map((r) => r.x)), y = Math.min(...rs.map((r) => r.y));
  return { x, y, w: Math.max(...rs.map((r) => r.x + r.w)) - x, h: Math.max(...rs.map((r) => r.y + r.h)) - y };
}
function allRect() { return sectionRect(GRAPH.sections.map((s) => s.id)); }
function viewFor(r, maxK = 0.8, safeRight = 0) {
  const { W: W0, H } = canvasSize();
  const W = Math.max(240, W0 - safeRight);
  const k = Math.min(maxK, Math.min((W - 40) / (r.w + 80), (H - 40) / (r.h + 80)));
  return { k, x: W / 2 - (r.x + r.w / 2) * k, y: H / 2 - (r.y + r.h / 2) * k };
}
// Zooming to a section leaves room on the right for the activity card; the whole-map fit uses the full canvas.
const feedSpace = () => { const f = $('#flowFeed'); return f.classList.contains('closed') ? 0 : f.offsetWidth + 24; };
function viewTo(r, animate, whole) {
  const t = viewFor(r, 0.8, whole ? 0 : feedSpace());
  cancelAnimationFrame(flow.tween);
  if (!animate || REDUCED) { Object.assign(flow, t); applyView(); return; }
  const { W, H } = canvasSize();
  const c0 = { x: (W / 2 - flow.x) / flow.k, y: (H / 2 - flow.y) / flow.k }, c1 = { x: (W / 2 - t.x) / t.k, y: (H / 2 - t.y) / t.k };
  const k0 = flow.k, t0 = performance.now(), D = 750;
  const step = (now) => {
    const p = Math.min(1, (now - t0) / D), e = p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;
    flow.k = k0 * Math.pow(t.k / k0, e);
    flow.x = W / 2 - (c0.x + (c1.x - c0.x) * e) * flow.k;
    flow.y = H / 2 - (c0.y + (c1.y - c0.y) * e) * flow.k;
    applyView(true);
    if (p < 1) flow.tween = requestAnimationFrame(step);
  };
  flow.tween = requestAnimationFrame(step);
}
function zoomAt(px, py, f) {
  const fit = viewFor(allRect()).k;
  const k2 = Math.min(2, Math.max(fit * 0.7, flow.k * f));
  flow.x = px - ((px - flow.x) * k2) / flow.k; flow.y = py - ((py - flow.y) * k2) / flow.k; flow.k = k2;
  applyView(true);
}
function applyView(moving) {
  const { k, x, y } = flow;
  $('#flowWorld').setAttribute('transform', `translate(${x.toFixed(2)} ${y.toFixed(2)}) scale(${k.toFixed(5)})`);
  $('#flowSvg').style.setProperty('--icw', Math.min(9, Math.max(3.5, 1.5 / k)).toFixed(2));
  let step = 100 * k; while (step < 18) step *= 2;
  const c = $('#canvas');
  c.style.backgroundSize = `${step}px ${step}px`;
  c.style.backgroundPosition = `${x % step}px ${y % step}px`;
  const ov = $('#flowOv');
  const labels = k >= 0.4;
  ov.classList.toggle('labels', labels);
  if (moving) { ov.classList.add('panning'); clearTimeout(flow.panTimer); flow.panTimer = setTimeout(() => ov.classList.remove('panning'), 160); }
  ov.querySelectorAll('.sl').forEach((el) => {
    const s = SEC[el.dataset.s];
    el.style.transform = `translate(${(s.x * k + x + 12).toFixed(1)}px, ${(s.y * k + y + 9).toFixed(1)}px)`;
    el.style.maxWidth = Math.max(40, s.w * k - 24) + 'px';
  });
  if (labels) ov.querySelectorAll('.nl').forEach((el) => {
    const n = N[el.dataset.n], w = Math.max(76, 170 * k);
    el.style.width = w + 'px';
    el.style.transform = `translate(${((n.x + 50) * k + x - w / 2).toFixed(1)}px, ${((n.y + n.h) * k + y + 5).toFixed(1)}px)`;
  });
  document.querySelectorAll('#flowPk .pk').forEach((c2) => c2.setAttribute('r', (4.2 / k).toFixed(1)));
  placeChips();
  $('#flowTip').hidden = true;
}

// ---- Interaction
function setFollow(on) {
  flow.follow = on;
  const b = $('#flowFollow');
  b.setAttribute('aria-pressed', String(on));
  b.textContent = on ? 'Following the run' : 'Follow the run';
  if (on) { flow.lastOn = 'resume'; updateFlow(); }
}
function wireCanvas() {
  const c = $('#canvas');
  c.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 || e.target.closest('button, a, .feed')) return;
    const sx = e.clientX, sy = e.clientY, ox = flow.x, oy = flow.y;
    let moved = false;
    const move = (ev) => {
      const dx = ev.clientX - sx, dy = ev.clientY - sy;
      if (!moved && Math.hypot(dx, dy) < 4) return;
      if (!moved) { moved = true; cancelAnimationFrame(flow.tween); setFollow(false); c.classList.add('grabbing'); try { c.setPointerCapture(e.pointerId); } catch (err) {} }
      flow.x = ox + dx; flow.y = oy + dy; applyView(true);
    };
    const up = () => { c.classList.remove('grabbing'); c.removeEventListener('pointermove', move); c.removeEventListener('pointerup', up); c.removeEventListener('pointercancel', up); };
    c.addEventListener('pointermove', move); c.addEventListener('pointerup', up); c.addEventListener('pointercancel', up);
  });
  c.addEventListener('wheel', (e) => {
    if (!e.ctrlKey && !e.metaKey) return;
    e.preventDefault(); cancelAnimationFrame(flow.tween); setFollow(false);
    const r = c.getBoundingClientRect();
    zoomAt(e.clientX - r.left, e.clientY - r.top, Math.exp(-e.deltaY * 0.01));
  }, { passive: false });
  const tip = () => $('#flowTip');
  $('#flowSvg').addEventListener('pointermove', (e) => {
    const g = e.target.closest && e.target.closest('.gn');
    if (!g || c.classList.contains('grabbing')) { tip().hidden = true; return; }
    const n = N[g.dataset.i], s = SEC[n.sec];
    tip().innerHTML = `<b>${esc(n.name)}</b><span>${esc(KIND_LABEL[n.kind] || 'Step')}${s ? '. ' + esc(s.title) : ''}</span>`;
    tip().hidden = false;
    tip().style.transform = `translate(calc(${((n.x + 50) * flow.k + flow.x).toFixed(1)}px - 50%), calc(${(n.y * flow.k + flow.y - 8).toFixed(1)}px - 100%))`;
  });
  $('#flowSvg').addEventListener('pointerleave', () => (tip().hidden = true));
  const center = () => { const { W, H } = canvasSize(); return [W / 2, H / 2]; };
  $('#flowIn').addEventListener('click', () => { cancelAnimationFrame(flow.tween); setFollow(false); zoomAt(...center(), 1.4); });
  $('#flowOut').addEventListener('click', () => { cancelAnimationFrame(flow.tween); setFollow(false); zoomAt(...center(), 1 / 1.4); });
  $('#flowFit').addEventListener('click', () => { setFollow(false); viewTo(allRect(), true, true); });
  $('#feedToggle').addEventListener('click', () => { const f = $('#flowFeed'); const closed = f.classList.toggle('closed'); $('#feedToggle').setAttribute('aria-expanded', String(!closed)); });
  $('#flowFollow').addEventListener('click', () => setFollow(!flow.follow));
}

// ---- Live state
// Flashes light a named path while the desk's own request is in flight (hold) or for a moment after (until).
function flash(path, opts = {}) {
  const f = { nodes: [...(opts.gate ? GRAPH.paths.gate : []), ...(GRAPH.paths[path] || [])], level: opts.level || 2, sec: opts.sec || 0,
    hold: !!opts.hold, until: Date.now() + (opts.ms || 1800), tag: opts.tag || path };
  flow.flashes.push(f);
  updateFlow();
  return f;
}
function release(f, ms) { if (!f) return; f.hold = false; f.until = Date.now() + (ms || 900); updateFlow(); }
const ACTION_PATH = { list: 'list', run: 'run', edit: 'edit', reset: 'reset', approve: 'decide', reject: 'decide', style_set: 'style', watch: 'watch', forget_rule: 'forget' };
function flowBegin(action) {
  const path = ACTION_PATH[action];
  if (!path) return null;
  return flash(path, { gate: true, hold: true, level: action === 'list' ? 1 : 2, sec: action === 'watch' ? 7 : ['approve', 'reject'].includes(action) ? 6 : 0 });
}
function flowEnd(f, action, r) {
  if (!f) return;
  if (r && r.error === 'passcode') { f.nodes = [...GRAPH.paths.gate, ...GRAPH.paths.refuse]; f.sec = 0; release(f, 1600); feedPush('The workflow refused a change: wrong passcode.', 1); return; }
  release(f, action === 'list' ? 500 : 1400);
  if (!r) return;
  const pick = (id) => (state.accounts.find((a) => a.account_id === id) || {}).company || 'the account';
  if (['approve', 'reject'].includes(action)) {
    const path = { sent: 'sent', rejected: 'rejected', skipped: 'skipped', failed: 'failed' }[r.result] || 'skipped';
    flash(path, { sec: 6, ms: 3200 });
    if (r.message) feedPush(r.message, 6);
  } else if (action === 'watch') {
    flow.ownWatchUntil = Date.now() + 60000;
    if (r.message) feedPush(r.message, 7);
    if ((r.drafting || []).length) flash('run', { ms: 2400 });
  } else if (action === 'run' && r.ok) feedPush(flow.lastRun ? `Redoing ${pick(flow.lastRun)}.` : 'Batch started. Triage runs first.', 1);
  else if (action === 'edit' && r.ok) { feedPush('Draft saved. The style learner is comparing your edit.', 1); flow.learnFlash = flash('learn', { hold: true }); setTimeout(() => release(flow.learnFlash), 60000); }
  else if (action === 'reset' && r.count != null) feedPush(`Demo CRM loaded: ${r.count} accounts.`, 1);
  else if (['style_set', 'forget_rule'].includes(action) && r.message) feedPush(r.message, 1);
}
function flowLearned(last) {
  release(flow.learnFlash, 1200); flow.learnFlash = null;
  feedPush((last.added || []).length ? `Learned: ${last.added.join(' ')}` : 'Your edit matched what Loopwell already knew.', 1);
}
function feedPush(text, sec) {
  flow.feed.unshift({ t: new Date(), text, sec: sec || 1 });
  flow.feed = flow.feed.slice(0, 8);
  renderFeed();
}
function renderFeed() {
  const el = $('#feedList');
  if (!el) return;
  el.innerHTML = flow.feed.length
    ? flow.feed.map((f) => `<li style="--h:${HUE[f.sec]}"><div><time>${f.t.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', second: '2-digit' })}</time>${esc(f.text)}</div></li>`).join('')
    : '<li class="none" style="display:block">Nothing yet. Run a batch or check for new signals, and each step shows up here as the workflow reports it.</li>';
}
// Compares each poll with the last one, so status moves and scheduled watcher runs land in the feed.
function trackChanges() {
  const moved = {};
  if (flow.prevStatus) state.accounts.forEach((a) => {
    const p = flow.prevStatus[a.account_id];
    if (p && p !== a.status) (moved[a.status] = moved[a.status] || []).push(a.company);
  });
  Object.entries(moved).forEach(([status, cos]) => {
    const list = cos.length > 3 ? `${cos.slice(0, 2).join(', ')} and ${cos.length - 2} more` : cos.length > 1 ? cos.slice(0, -1).join(', ') + ' and ' + cos[cos.length - 1] : cos[0];
    feedPush(`${list} moved to ${(STATUS[status] || { label: status }).label}.`, STAGE_OF[status] || (['awaiting_approval', 'sent', 'rejected'].includes(status) ? 6 : 1));
  });
  flow.prevStatus = Object.fromEntries(state.accounts.map((a) => [a.account_id, a.status]));
  const last = (state.watcher || {}).last_check || '';
  if (flow.prevWatch != null && last && last !== flow.prevWatch && Date.now() > flow.ownWatchUntil) {
    flash('schedule', { sec: 7, ms: 4000 });
    feedPush(`The watcher checked ${(state.watcher || {}).watching || 0} sites.`, 7);
  }
  flow.prevWatch = last;
}

function chipAnchor(group) {
  const { k, x, y } = flow;
  if (group.startsWith('s')) { const s = SEC[group.slice(1)]; return { x: (s.x + s.w / 2) * k + x, y: s.y * k + y - 10, up: true }; }
  const n = NODE[group.slice(1)] || NODE['CRM: read for run'];
  return { x: (n.x + 50) * k + x, y: (n.y + n.h) * k + y + (k >= 0.4 ? 34 : 6), up: false };
}
function placeChips() {
  const groups = {};
  state.accounts.forEach((a) => {
    const s = STAGE_OF[a.status];
    const g = s ? 's' + s : 'n' + (ANCHOR[a.status] || 'CRM: read for run');
    (groups[g] = groups[g] || []).push(a.account_id);
  });
  Object.entries(groups).forEach(([g, ids]) => {
    const an = chipAnchor(g);
    ids.forEach((id, i) => {
      const chip = flow.chips.get(id);
      if (!chip) return;
      const row = Math.floor(i / 4), inRow = Math.min(4, ids.length - row * 4), col = i % 4;
      const cx = an.x + (col - (inRow - 1) / 2) * 25 - 11;
      const cy = an.up ? an.y - 22 - row * 25 : an.y + row * 25;
      chip.style.transform = `translate(${cx.toFixed(1)}px, ${cy.toFixed(1)}px)`;
    });
  });
}

function flowStatusText(counts) {
  const running = Object.entries(counts).map(([s, n]) => `${n} account${n === 1 ? '' : 's'} in ${STAGE_NAME[s]}`);
  const holding = flow.flashes.find((f) => f.hold && f.level === 2);
  if (running.length) return `Running now: ${running.join(', ')}.`;
  if (holding && holding.tag === 'watch') return 'Checking every open account\'s homepage and news for new signals…';
  if (holding && holding.tag === 'decide') return 'Sending through Gmail…';
  const wait = state.accounts.filter((a) => a.status === 'awaiting_approval').length;
  return wait ? `Idle. ${wait} draft${wait === 1 ? ' is' : 's are'} waiting for your review.` : 'Idle. Nothing is running.';
}

function updateFlow() {
  const counts = {};
  state.accounts.forEach((a) => { const s = STAGE_OF[a.status]; if (s) counts[s] = (counts[s] || 0) + 1; });
  const running = Object.keys(counts).length > 0;
  $('#flowMeta').innerHTML = running ? '<i></i>Running now' : `${N.length} nodes, updates live`;
  if (!flow.built || !$('#flow').open) return;
  const lit = new Map();
  const onSecs = new Set(Object.keys(counts).map(Number));
  onSecs.forEach((s) => SEC_NODES[s].forEach((i) => lit.set(i, 2)));
  const now = Date.now();
  flow.flashes = flow.flashes.filter((f) => f.hold || f.until > now);
  flow.flashes.forEach((f) => { f.nodes.forEach((i) => lit.set(i, Math.max(lit.get(i) || 0, f.level))); if (f.sec && f.level === 2) onSecs.add(f.sec); });
  GRAPH.ai.forEach(([m, t]) => { if (lit.get(t) === 2) lit.set(m, 2); });
  document.querySelectorAll('#flowSvg .gn').forEach((g) => {
    const l = lit.get(+g.dataset.i) || 0;
    g.classList.toggle('on', l === 2); g.classList.toggle('tick', l === 1);
  });
  const onEdges = [];
  document.querySelectorAll('#flowSvg .ge').forEach((p) => {
    const [a, , b] = GRAPH.edges[+p.dataset.e];
    const l = Math.min(lit.get(a) || 0, lit.get(b) || 0);
    p.classList.toggle('on', l === 2); p.classList.toggle('tick', l === 1);
    if (l === 2) onEdges.push(+p.dataset.e);
  });
  document.querySelectorAll('#flowSvg .ga').forEach((p) => p.classList.toggle('on', lit.get(GRAPH.ai[+p.dataset.e][1]) === 2));
  document.querySelectorAll('#flowSvg .sec').forEach((g) => g.classList.toggle('on', onSecs.has(+g.dataset.s)));
  // Dots travel along the lit connections.
  const key = onEdges.join(',');
  if (key !== flow.pkKey) {
    flow.pkKey = key;
    $('#flowPk').innerHTML = REDUCED ? '' : onEdges.map((i) => {
      const dur = Math.min(2.6, Math.max(0.7, flow.len[i] / 520)).toFixed(2);
      return `<circle class="pk" r="${(4.2 / flow.k).toFixed(1)}" style="--h:${HUE[N[GRAPH.edges[i][2]].sec]}"><animateMotion dur="${dur}s" repeatCount="indefinite"><mpath href="#fe${i}" xlink:href="#fe${i}"/></animateMotion></circle>`;
    }).join('');
  }
  // Section badges
  const w = state.watcher || {};
  const waiting = state.accounts.filter((a) => ['awaiting_approval', 'rejected'].includes(a.status)).length;
  const sent = state.accounts.filter((a) => ['sent', 'in_gmail'].includes(a.status)).length;
  const badge = {
    6: [waiting ? `${waiting} waiting` : '', sent ? `${sent} sent` : ''].filter(Boolean).join(', '),
    7: w.last_check ? `Checked ${new Date(w.last_check).toDateString() === new Date().toDateString() ? new Date(w.last_check).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : fmtDate(String(w.last_check).slice(0, 10))}` : '',
  };
  Object.entries(counts).forEach(([s, n]) => (badge[s] = `${n} account${n === 1 ? '' : 's'} here`));
  document.querySelectorAll('#flowOv .bd').forEach((el) => {
    const s = +el.dataset.bd, text = badge[s] || '';
    el.innerHTML = text ? (onSecs.has(s) ? '<i></i>' : '') + esc(text) : (onSecs.has(s) ? '<i></i>Running' : '');
  });
  // Account chips
  const ov = $('#flowOv'), seen = new Set();
  state.accounts.forEach((a) => {
    let chip = flow.chips.get(a.account_id);
    if (!chip) {
      chip = document.createElement('button');
      chip.type = 'button';
      chip.addEventListener('click', () => select(a.account_id));
      ov.appendChild(chip); flow.chips.set(a.account_id, chip);
    }
    const s = st(a);
    chip.className = `gchip ${s.tone}${state.selected === a.account_id ? ' sel' : ''}`;
    chip.textContent = initials(a.company);
    chip.title = `${a.company}: ${s.label}`;
    chip.setAttribute('aria-label', `${a.company}, ${s.label}`);
    seen.add(a.account_id);
  });
  flow.chips.forEach((c, id) => { if (!seen.has(id)) { c.remove(); flow.chips.delete(id); } });
  placeChips();
  $('#flowStatus').textContent = flowStatusText(counts);
  $('#canvas').setAttribute('aria-label', 'Live map of the Loopwell workflow in n8n. ' + flowStatusText(counts));
  // Follow the run: glide to whatever is active, and back to the whole map when it goes quiet.
  const onKey = [...onSecs].sort().join(',');
  if (flow.follow && onKey !== flow.lastOn) {
    const first = flow.lastOn === null; // just opened or resized: jump instead of gliding
    flow.lastOn = onKey;
    if (onKey) viewTo(sectionRect([...onSecs]), !first); else viewTo(allRect(), !first, true);
  }
  clearTimeout(flow.timer);
  const next = flow.flashes.filter((f) => !f.hold).map((f) => f.until).sort((a, b) => a - b)[0];
  if (next) flow.timer = setTimeout(updateFlow, Math.max(60, next - Date.now() + 30));
}

$('#flow').addEventListener('toggle', () => {
  const open = $('#flow').open;
  $('#flowSum').textContent = open ? 'Hide the live workflow' : 'Show the live workflow';
  if (!open) return;
  buildFlow();
  renderFeed();
  flow.lastOn = null;
  requestAnimationFrame(() => updateFlow());
});

