// A quote only closes a string when what follows is JSON structure (: , } ]), never prose.
const CLOSES_STRING = /\s*(?:[:}\]]|$|,\s*(?:"|\{|\[|\}|\]|-?\d|true\b|false\b|null\b))/y;
